-- Screenshot-only demo data for a clean debug emulator.
-- The matching generated photos live in docs/demo/photos/.
PRAGMA foreign_keys = ON;
BEGIN;
DELETE FROM attachments;
DELETE FROM monthly_recaps;
DELETE FROM diary_pages;




-- JSON needs escaped newlines; the search/list cache needs real newlines.
UPDATE diary_pages SET plainText = replace(plainText, '\n', char(10));
UPDATE monthly_recaps SET plainText = replace(plainText, '\n', char(10));
COMMIT;
