INSERT INTO diary_pages VALUES
('page-2026-08-03','2026-08-03','{"text":"A slower start\n\nOpened every window before breakfast and let the apartment wake up with me. I kept the day deliberately empty.","marks":[{"start":0,"end":14,"style":"Heading"}]}','A slower start\n\nOpened every window before breakfast and let the apartment wake up with me. I kept the day deliberately empty.',1785729600000,1785729600000,1,NULL,NULL,NULL,NULL,0),
('page-2026-08-04','2026-08-04','{"text":"The long way home\n\nI left my headphones in my bag and noticed how much of the city I normally hurry past. It was good to wander without turning it into a task.","marks":[{"start":0,"end":17,"style":"Heading"}]}','The long way home\n\nI left my headphones in my bag and noticed how much of the city I normally hurry past. It was good to wander without turning it into a task.',1785816000000,1785816000000,1,NULL,'Zurenborg, Antwerp',51.2073,4.4329,1),
('page-2026-08-05','2026-08-05','{"text":"Rain against the window\n\nThe weather changed before lunch, so I hid in a little café with a book and nowhere else to be. The rain made the whole street feel quieter.","marks":[{"start":0,"end":23,"style":"Heading"}]}','Rain against the window\n\nThe weather changed before lunch, so I hid in a little café with a book and nowhere else to be. The rain made the whole street feel quieter.',1785902400000,1785902400000,1,NULL,'Sint-Andries, Antwerp',51.2144,4.3977,1),
('page-2026-08-06','2026-08-06','{"text":"Following the water\n\nTook the bicycle along the canal with no destination in mind. There was a warm breeze, almost no traffic, and enough time to stop whenever the view changed.","marks":[{"start":0,"end":19,"style":"Heading"}]}','Following the water\n\nTook the bicycle along the canal with no destination in mind. There was a warm breeze, almost no traffic, and enough time to stop whenever the view changed.',1785988800000,1785988800000,1,NULL,'Coupure, Ghent',51.0526,3.7104,1),
('page-2026-08-07','2026-08-07','{"text":"Market morning\n\nBought peaches that were already a little too soft and a bunch of flowers I absolutely did not need. Carried both home like treasure.","marks":[{"start":0,"end":14,"style":"Heading"}]}','Market morning\n\nBought peaches that were already a little too soft and a bunch of flowers I absolutely did not need. Carried both home like treasure.',1786075200000,1786075200000,1,NULL,'Vogelenmarkt, Antwerp',51.2158,4.4107,1),
('page-2026-08-08','2026-08-08','{"text":"Nothing urgent\n\nLate breakfast, flowers on the table, and the rare feeling that the morning could take as long as it wanted.","marks":[{"start":0,"end":14,"style":"Heading"}]}','Nothing urgent\n\nLate breakfast, flowers on the table, and the rare feeling that the morning could take as long as it wanted.',1786161600000,1786161600000,1,NULL,NULL,NULL,NULL,0),
('page-2026-08-09','2026-08-09','{"text":"After the rain\n\nThe forest smelled like wet earth and leaves. My shoes were muddy within ten minutes, which felt like permission to stop trying to stay clean.","marks":[{"start":0,"end":14,"style":"Heading"}]}','After the rain\n\nThe forest smelled like wet earth and leaves. My shoes were muddy within ten minutes, which felt like permission to stop trying to stay clean.',1786248000000,1786248000000,1,NULL,'Sonian Forest',50.7860,4.4170,1),
('page-2026-08-10','2026-08-10','{"text":"Blue hour\n\nWalked home after the storm. Every window looked warmer against the wet street, and for once I did not mind missing the tram.","marks":[{"start":0,"end":9,"style":"Heading"}]}','Blue hour\n\nWalked home after the storm. Every window looked warmer against the wet street, and for once I did not mind missing the tram.',1786334400000,1786334400000,1,NULL,'Historic Centre, Antwerp',51.2206,4.4005,1),
('page-2026-08-11','2026-08-11','{"text":"Room to breathe\n\nCleared my desk, answered the messages I had been avoiding, and cooked something simple. Not an exciting day, but a kind one.","marks":[{"start":0,"end":15,"style":"Heading"}]}','Room to breathe\n\nCleared my desk, answered the messages I had been avoiding, and cooked something simple. Not an exciting day, but a kind one.',1786420800000,1786420800000,1,NULL,NULL,NULL,NULL,0),
('page-2026-08-12','2026-08-12','{"text":"Golden hour, no plans\n\nWe packed bread, strawberries, and two cups, then stayed in the park until the sky turned peach. Nothing remarkable happened. That was exactly the point.\n\nI want to remember how unhurried everything felt.","marks":[{"start":0,"end":21,"style":"Heading"},{"start":96,"end":124,"style":"Italic"}]}','Golden hour, no plans\n\nWe packed bread, strawberries, and two cups, then stayed in the park until the sky turned peach. Nothing remarkable happened. That was exactly the point.\n\nI want to remember how unhurried everything felt.',1786507200000,1786507200000,1,NULL,'Rivierenhof, Antwerp',51.2150,4.4750,1);
INSERT INTO monthly_recaps VALUES
('recap-2026-08','2026-08','{"text":"August, so far\n\nThis month has felt softer than the last one. I rode farther, walked more slowly, and made room for ordinary afternoons instead of waiting for a perfect occasion.\n\nThings I want to carry forward: leaving space in the calendar, buying the flowers, and taking the long way home.","marks":[{"start":0,"end":14,"style":"Heading"},{"start":178,"end":209,"style":"Bold"}]}','August, so far\n\nThis month has felt softer than the last one. I rode farther, walked more slowly, and made room for ordinary afternoons instead of waiting for a perfect occasion.\n\nThings I want to carry forward: leaving space in the calendar, buying the flowers, and taking the long way home.',1786507200000,1786507200000,1,NULL);
